create table if not exists proof_projects (id uuid primary key, owner_id uuid not null references platform_users(id) on delete cascade, name text not null, client_name text not null, client_email text, description text not null default '', due_date date, status text not null default 'Draft' check(status in ('Draft','Awaiting Review','Changes Requested','Approved','Completed')), archived_at timestamptz, created_at timestamptz not null default now());
create table if not exists proof_deliverables (id uuid primary key, project_id uuid not null references proof_projects(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table if not exists proof_versions (id uuid primary key, deliverable_id uuid not null references proof_deliverables(id) on delete cascade, version_number integer not null, original_name text not null, storage_name text not null unique, mime_type text not null, size_bytes integer not null check(size_bytes > 0), created_at timestamptz not null default now(), unique(deliverable_id,version_number));
create table if not exists proof_review_links (id uuid primary key, project_id uuid not null references proof_projects(id) on delete cascade, token_hash text not null unique, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create index if not exists proof_projects_owner on proof_projects(owner_id,created_at desc);
